-- Gerado por scripts/importar-lugares.py (bbox -23.10,-43.80,-22.74,-43.10, Overture 2026-09-23.1).
-- 2924 lugares pet: OpenStreetMap (ODbL) e Overture Maps (CDLA-Permissive-2.0,
-- com dados da Meta, Microsoft e Foursquare/Apache-2.0). Créditos em docs/dados-abertos.md.
-- Um comando só (o `db query -f` usa prepared statement); upsert idempotente.
on conflict (fonte, fonte_id) do update set
  osm_type = excluded.osm_type,
  osm_id = excluded.osm_id,
  nome = excluded.nome,
  categoria = excluded.categoria,
  endereco = excluded.endereco,
  telefone = excluded.telefone,
  horario = excluded.horario,
  website = excluded.website,
  lat = excluded.lat,
  lng = excluded.lng,
  aberto_24h = excluded.aberto_24h,
  aceita_caes = excluded.aceita_caes,
  area_caes = excluded.area_caes;
